arguments.command:
cd /tmp && for id in 8110 8116 8117 8118 8112 8114; do curl -s "https://api.box.com/2.0/files/$id" -H "Authorization: Bearer <TOKEN>" > f_$id.json; done; python3 - <<'EOF'
import json, itertools
ids = [8110,8116,8117,8118,8112,8114]
docs = {i: json.load(open(f'f_{i}.json')) for i in ids}
# union of keys
keys = set()
for d in docs.values():
    keys |= set(d.keys())
for k in sorted(keys):
    vals = {i: json.dumps(docs[i].get(k), sort_keys=True) for i in ids}
    if len(set(vals.values())) > 1:
        print(k)
        for i in ids:
            print('  ', i, vals[i][:200])
EOF

